import { Link, Stack } from "@carbon/react";
import type { ContentBlockSchema, ContentPageSchema } from "./schema";
import { say, type Texts } from "./texts";

export interface ContentPageProps {
  readonly schema: ContentPageSchema;
  readonly texts: Texts;
  readonly routes: Readonly<Record<string, string>>;
}

function Block({ block, texts, routes }: { readonly block: ContentBlockSchema; readonly texts: Texts; readonly routes: Readonly<Record<string, string>> }) {
  switch (block.kind) {
    case "heading": {
      const Heading = `h${block.level}` as const;
      return <Heading>{say(texts, block.text)}</Heading>;
    }
    case "text":
      return <p>{say(texts, block.text)}</p>;
    case "image":
      // The image is the project's file, of a size the design leaves to it,
      // so it is drawn as it is rather than through next/image, which needs
      // its width and height.
      // eslint-disable-next-line @next/next/no-img-element
      return <img src={block.path} alt={say(texts, block.alternativeText)} />;
    case "link":
      return (
        <p>
          <Link href={block.page !== undefined ? (routes[block.page] ?? "/") : block.href}>{say(texts, block.label)}</Link>
        </p>
      );
  }
}

/**
 * A page of headings, paragraphs, images and links under its title, in the
 * order a person reads them; it loads and sends nothing.
 */
export function ContentPage({ schema, texts, routes }: ContentPageProps) {
  return (
    <section className="screens-content">
      <h1>{say(texts, schema.title)}</h1>
      <Stack gap={5}>
        {schema.blocks.map((block, index) => (
          <Block key={index} block={block} texts={texts} routes={routes} />
        ))}
      </Stack>
    </section>
  );
}
